package raft

import (
	"bytes"
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func caEvent(m map[string]interface{}) {
	b, _ := json.Marshal(m)
	fmt.Println("CA_EVENT " + string(b))
}

// buildNode creates a node under test ("server-1") that is a Nonvoter in a
// configuration whose only Voter is a remote "server-2", so it never campaigns.
func buildNode(t *testing.T) (*Raft, *InmemTransport, ServerAddress) {
	addr1, trans1 := NewInmemTransport("server-1")
	addr2, trans2 := NewInmemTransport("server-2")
	trans1.Connect(addr2, trans2)
	trans2.Connect(addr1, trans1)

	conf := inmemConfig(t)
	conf.LocalID = ServerID("server-1")
	conf.ProtocolVersion = 3
	conf.SnapshotThreshold = 1 << 20
	conf.SnapshotInterval = time.Hour
	conf.skipStartup = false

	store := NewInmemStore()
	snaps := NewInmemSnapshotStore()
	fsm := &MockFSM{}

	configuration := Configuration{Servers: []Server{
		{Suffrage: Voter, ID: ServerID("server-2"), Address: addr2},
		{Suffrage: Nonvoter, ID: ServerID("server-1"), Address: addr1},
	}}
	if err := BootstrapCluster(conf, store, store, snaps, trans1, configuration); err != nil {
		t.Fatalf("bootstrap: %v", err)
	}
	r, err := NewRaft(conf, fsm, store, store, snaps, trans1)
	if err != nil {
		t.Fatalf("NewRaft: %v", err)
	}
	return r, trans2, addr1
}

func snapshotPayload(t *testing.T) []byte {
	buf, err := encodeMsgPack([][]byte{})
	if err != nil {
		t.Fatalf("encodeMsgPack: %v", err)
	}
	return buf.Bytes()
}

func TestAssurance_SnapshotBoundaryStaleEntry(t *testing.T) {
	for _, stale := range []bool{false, true} {
		name := fmt.Sprintf("stale_same_index_entry=%v", stale)
		t.Run(name, func(t *testing.T) {
			r, trans2, addr1 := buildNode(t)
			defer r.Shutdown()
			time.Sleep(50 * time.Millisecond) // let run()/runFSM() start

			id1 := ServerID("server-1")
			hdr := RPCHeader{ProtocolVersion: 3, ID: []byte("server-2"), Addr: trans2.EncodePeer("server-2", "server-2")}
			leader := trans2.EncodePeer("server-2", "server-2")

			// Step 1: a previous leader of term 2 stores a command at index 2.
			if stale {
				ae := &AppendEntriesRequest{
					RPCHeader:         hdr,
					Term:              2,
					Leader:            leader,
					PrevLogEntry:      1,
					PrevLogTerm:       1,
					Entries:           []*Log{{Index: 2, Term: 2, Type: LogCommand, Data: []byte("old-term")}},
					LeaderCommitIndex: 1,
				}
				var resp AppendEntriesResponse
				if err := trans2.AppendEntries(id1, addr1, ae, &resp); err != nil {
					t.Fatalf("appendEntries(seed): %v", err)
				}
				caEvent(map[string]interface{}{"event": "seed_append", "success": resp.Success, "term": resp.Term})
				if !resp.Success {
					t.Fatalf("seed append failed")
				}
				time.Sleep(50 * time.Millisecond)
			}

			// Step 2: a new leader of term 3 installs a snapshot whose last
			// included index is 2.
			payload := snapshotPayload(t)
			conf := Configuration{Servers: []Server{
				{Suffrage: Voter, ID: ServerID("server-2"), Address: "server-2"},
				{Suffrage: Nonvoter, ID: ServerID("server-1"), Address: "server-1"},
			}}
			isr := &InstallSnapshotRequest{
				RPCHeader:          hdr,
				SnapshotVersion:    1,
				Term:               3,
				Leader:             leader,
				LastLogIndex:       2,
				LastLogTerm:        3,
				Configuration:      EncodeConfiguration(conf),
				ConfigurationIndex: 1,
				Size:               int64(len(payload)),
			}
			var isResp InstallSnapshotResponse
			if err := trans2.InstallSnapshot(id1, addr1, isr, &isResp, bytes.NewReader(payload)); err != nil {
				t.Fatalf("installSnapshot: %v", err)
			}
			caEvent(map[string]interface{}{"event": "install_snapshot", "success": isResp.Success, "term": isResp.Term})
			time.Sleep(50 * time.Millisecond)

			li, lt := r.getLastLog()
			si, st := r.getLastSnapshot()
			ei, et := r.getLastEntry()
			caEvent(map[string]interface{}{
				"event": "state_after_snapshot", "last_log_index": li, "last_log_term": lt,
				"last_snapshot_index": si, "last_snapshot_term": st,
				"get_last_entry_index": ei, "get_last_entry_term": et,
				"get_last_index": r.getLastIndex(), "get_last_applied": r.getLastApplied(),
			})

			// Step 3: the leader replicates the entry right after the snapshot
			// boundary, whose PrevLogEntry/Term is exactly the snapshot's.
			ae2 := &AppendEntriesRequest{
				RPCHeader:         hdr,
				Term:              3,
				Leader:            leader,
				PrevLogEntry:      2,
				PrevLogTerm:       3,
				Entries:           []*Log{{Index: 3, Term: 3, Type: LogCommand, Data: []byte("new")}},
				LeaderCommitIndex: 2,
			}
			var resp2 AppendEntriesResponse
			if err := trans2.AppendEntries(id1, addr1, ae2, &resp2); err != nil {
				t.Fatalf("appendEntries(post-snapshot): %v", err)
			}
			caEvent(map[string]interface{}{
				"event": "post_snapshot_append", "stale_seed": stale,
				"success": resp2.Success, "no_retry_backoff": resp2.NoRetryBackoff,
				"resp_term": resp2.Term, "resp_last_log": resp2.LastLog,
			})
		})
	}
}

package raft

import (
	"encoding/json"
	"fmt"
	"io"
	"sync"
	"testing"
	"time"
)

func caEvent(m map[string]interface{}) {
	b, _ := json.Marshal(m)
	fmt.Println("CA_EVENT " + string(b))
}

// countingTrans counts InstallSnapshot calls the leader makes to its peers.
type countingTrans struct {
	*InmemTransport
	mu    sync.Mutex
	snaps int
}

func (c *countingTrans) InstallSnapshot(id ServerID, target ServerAddress, args *InstallSnapshotRequest, resp *InstallSnapshotResponse, data io.Reader) error {
	c.mu.Lock()
	c.snaps++
	c.mu.Unlock()
	return c.InmemTransport.InstallSnapshot(id, target, args, resp, data)
}

func (c *countingTrans) SnapshotCount() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.snaps
}

func waitState(t *testing.T, r *Raft, want RaftState, limit time.Duration) bool {
	deadline := time.Now().Add(limit)
	for time.Now().Before(deadline) {
		if r.State() == want {
			return true
		}
		time.Sleep(5 * time.Millisecond)
	}
	return false
}

func TestAssurance_SnapshotBoundaryLoop(t *testing.T) {
	for _, stale := range []bool{false, true} {
		t.Run(fmt.Sprintf("stale_index_entry=%v", stale), func(t *testing.T) {
			// --- Leader A: single-voter cluster, becomes leader on its own.
			addrA, rawA := NewInmemTransport("server-A")
			transA := &countingTrans{InmemTransport: rawA}
			confA := inmemConfig(t)
			confA.LocalID = ServerID("server-A")
			confA.ProtocolVersion = 3
			confA.TrailingLogs = 0
			confA.SnapshotThreshold = 1 << 20
			confA.SnapshotInterval = time.Hour
			storeA := NewInmemStore()
			snapsA := NewInmemSnapshotStore()
			fsmA := &MockFSM{}
			cfgA := Configuration{Servers: []Server{{Suffrage: Voter, ID: ServerID("server-A"), Address: addrA}}}
			if err := BootstrapCluster(confA, storeA, storeA, snapsA, transA, cfgA); err != nil {
				t.Fatalf("bootstrap A: %v", err)
			}
			leader, err := NewRaft(confA, fsmA, storeA, storeA, snapsA, transA)
			if err != nil {
				t.Fatalf("NewRaft A: %v", err)
			}
			defer leader.Shutdown()
			if !waitState(t, leader, Leader, 5*time.Second) {
				t.Fatalf("A never became leader")
			}
			for i := 0; i < 6; i++ {
				if err := leader.Apply([]byte(fmt.Sprintf("cmd-%d", i)), 2*time.Second).Error(); err != nil {
					t.Fatalf("apply: %v", err)
				}
			}
			sf := leader.Snapshot()
			if err := sf.Error(); err != nil {
				t.Fatalf("snapshot: %v", err)
			}
			meta, rc, err := sf.Open()
			if err != nil {
				t.Fatalf("snapshot open: %v", err)
			}
			snapIdx := meta.Index
			rc.Close()
			firstA, _ := storeA.FirstIndex()
			caEvent(map[string]interface{}{"event": "leader_snapshot", "snapshot_index": snapIdx, "leader_first_index": firstA,
				"leader_last_index": leader.LastIndex(), "leader_commit_index": leader.CommitIndex()})

			// --- Follower B: Nonvoter in A's configuration so it never campaigns.
			addrB, rawB := NewInmemTransport("server-B")
			confB := inmemConfig(t)
			confB.LocalID = ServerID("server-B")
			confB.ProtocolVersion = 3
			confB.SnapshotThreshold = 1 << 20
			confB.SnapshotInterval = time.Hour
			storeB := NewInmemStore()
			snapsB := NewInmemSnapshotStore()
			fsmB := &MockFSM{}
			cfgB := Configuration{Servers: []Server{
				{Suffrage: Voter, ID: ServerID("server-A"), Address: addrA},
				{Suffrage: Nonvoter, ID: ServerID("server-B"), Address: addrB},
			}}
			if err := BootstrapCluster(confB, storeB, storeB, snapsB, rawB, cfgB); err != nil {
				t.Fatalf("bootstrap B: %v", err)
			}
			follower, err := NewRaft(confB, fsmB, storeB, storeB, snapsB, rawB)
			if err != nil {
				t.Fatalf("NewRaft B: %v", err)
			}
			defer follower.Shutdown()
			time.Sleep(50 * time.Millisecond)

			// Seed B with earlier-term (term 1) entries up to snapIdx (defect)
			// or snapIdx-1 (control), delivered as a legal AppendEntries.
			target := snapIdx
			if !stale {
				target = snapIdx - 1
			}
			addrD, rawD := NewInmemTransport("dummy")
			rawD.Connect(addrB, rawB)
			rawB.Connect(addrD, rawD)
			var entries []*Log
			for i := uint64(2); i <= target; i++ {
				entries = append(entries, &Log{Index: i, Term: 1, Type: LogCommand, Data: []byte("old")})
			}
			encA := rawD.EncodePeer("server-A", addrA)
			seed := &AppendEntriesRequest{
				RPCHeader:         RPCHeader{ProtocolVersion: 3, ID: []byte("server-A"), Addr: encA},
				Term:              1,
				Leader:            encA,
				PrevLogEntry:      1,
				PrevLogTerm:       1,
				Entries:           entries,
				LeaderCommitIndex: 1,
			}
			var seedResp AppendEntriesResponse
			if err := rawD.AppendEntries(ServerID("server-B"), addrB, seed, &seedResp); err != nil {
				t.Fatalf("seed: %v", err)
			}
			if !seedResp.Success {
				t.Fatalf("seed rejected: %+v", seedResp)
			}
			time.Sleep(50 * time.Millisecond)

			// --- Connect A and B, then add B as a voter of A.
			rawA.Connect(addrB, rawB)
			rawB.Connect(addrA, rawA)
			_ = leader.AddVoter(ServerID("server-B"), addrB, 0, time.Second)

			time.Sleep(300 * time.Millisecond)
			early := transA.SnapshotCount()
			time.Sleep(1200 * time.Millisecond)
			late := transA.SnapshotCount()
			caEvent(map[string]interface{}{
				"event": "loop_observe", "stale_index_entry": stale,
				"snapshot_index": snapIdx, "install_snapshot_calls_early": early, "install_snapshot_calls_late": late,
				"follower_applied_index": follower.AppliedIndex(), "follower_last_index": follower.LastIndex(),
				"leader_last_index": leader.LastIndex(), "leader_commit_index": leader.CommitIndex(),
			})
		})
	}
}

package raft

import (
	"io"
	"encoding/json"
	"fmt"
	"sync"
	"testing"
	"time"
)

type countFSM struct {
	*MockFSM
	mu       sync.Mutex
	restores int
}

func (c *countFSM) Restore(in io.ReadCloser) error {
	c.mu.Lock()
	c.restores++
	c.mu.Unlock()
	return c.MockFSM.Restore(in)
}

func (c *countFSM) RestoreCount() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.restores
}

func TestAssurance_ReachabilityDivergentSuffix(t *testing.T) {
	conf := inmemConfig(t)
	conf.TrailingLogs = 0
	conf.SnapshotThreshold = 1 << 20
	conf.SnapshotInterval = time.Hour
	conf.LeaderLeaseTimeout = 1 * time.Second
	conf.ElectionTimeout = 1 * time.Second
	conf.HeartbeatTimeout = 1 * time.Second
	conf.CommitTimeout = 10 * time.Millisecond

	var fsms []*countFSM
	c := MakeClusterCustom(t, &MakeClusterOpts{
		Peers: 5, Bootstrap: true, Conf: conf, LongstopTimeout: 5 * time.Second,
		MakeFSMFunc: func() FSM { f := &countFSM{MockFSM: &MockFSM{}}; fsms = append(fsms, f); return f },
	})
	defer c.Close()

	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) && c.Leader() == nil {
		time.Sleep(10 * time.Millisecond)
	}
	leader := c.Leader()
	if leader == nil {
		t.Fatalf("no leader")
	}
	followers := c.Followers()
	if len(followers) < 4 {
		t.Fatalf("want 4 followers, got %d", len(followers))
	}
	partner := followers[0]
	var others []*Raft
	for _, r := range c.rafts {
		if r != leader && r != partner {
			others = append(others, r)
		}
	}
	if len(others) != 3 {
		t.Fatalf("want 3 others, got %d", len(others))
	}

	// Isolate the leader from the other three, keeping leader<->partner.
	lt := c.trans[c.IndexOf(leader)]
	for _, o := range others {
		lt.Disconnect(o.localAddr)
		c.trans[c.IndexOf(o)].Disconnect(leader.localAddr)
	}

	base := leader.LastIndex()
	// Leader appends entries that reach only the partner (no quorum).
	for i := 0; i < 5; i++ {
		leader.Apply([]byte(fmt.Sprintf("uncommitted-%d", i)), 0)
	}
	ok := false
	for d := time.Now().Add(3 * time.Second); time.Now().Before(d); {
		if partner.LastIndex() > base {
			ok = true
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	caEvent(map[string]interface{}{"event": "divergent_prefix", "base_index": base,
		"partner_last_index": partner.LastIndex(), "partner_replicated_uncommitted": ok,
		"leader_last_index": leader.LastIndex()})
	if !ok {
		t.Fatalf("partner never received the uncommitted suffix")
	}

	// The majority side elects a new leader with a shorter log.
	var newLeader *Raft
	for d := time.Now().Add(10 * time.Second); time.Now().Before(d); {
		for _, o := range others {
			if o.State() == Leader {
				newLeader = o
			}
		}
		if newLeader != nil {
			break
		}
		time.Sleep(10 * time.Millisecond)
	}
	if newLeader == nil {
		t.Fatalf("majority side never elected a leader")
	}
	// The new leader must apply a real command before it has anything to
	// snapshot; the resulting snapshot index lands inside the suffix the
	// partner already holds at the older term.
	if err := newLeader.Apply([]byte("post-election"), 5*time.Second).Error(); err != nil {
		t.Fatalf("post-election apply: %v", err)
	}
	for d := time.Now().Add(5 * time.Second); time.Now().Before(d); {
		if newLeader.AppliedIndex() >= base+1 {
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	sf := newLeader.Snapshot()
	if err := sf.Error(); err != nil {
		t.Fatalf("snapshot: %v", err)
	}
	meta, rc, err := sf.Open()
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	snapIdx := meta.Index
	rc.Close()
	caEvent(map[string]interface{}{"event": "new_leader_snapshot", "snapshot_index": snapIdx,
		"divergence_index": base + 1, "new_leader_last_index": newLeader.LastIndex(),
		"new_leader_term": newLeader.CurrentTerm(), "old_leader_term": leader.CurrentTerm()})

	pidx := c.IndexOf(partner)
	before := fsms[pidx].RestoreCount()
	c.FullyConnect()
	time.Sleep(300 * time.Millisecond)
	early := fsms[pidx].RestoreCount()
	time.Sleep(1200 * time.Millisecond)
	late := fsms[pidx].RestoreCount()
	caEvent(map[string]interface{}{"event": "rejoin_observe", "restores_before": before,
		"restores_early": early, "restores_late": late,
		"partner_applied_index": partner.AppliedIndex(), "partner_last_index": partner.LastIndex(),
		"new_leader_applied_index": newLeader.AppliedIndex(), "new_leader_commit_index": newLeader.CommitIndex()})

	b, _ := json.Marshal(map[string]interface{}{"event": "done"})
	fmt.Println("CA_EVENT " + string(b))
}

package raft

import (
	"encoding/json"
	"fmt"
	"io"
	"sync"
	"testing"
	"time"
)

func caEvent(m map[string]interface{}) {
	b, _ := json.Marshal(m)
	fmt.Println("CA_EVENT " + string(b))
}

type countFSM struct {
	*MockFSM
	mu       sync.Mutex
	restores int
}

func (c *countFSM) Restore(in io.ReadCloser) error {
	c.mu.Lock()
	c.restores++
	c.mu.Unlock()
	return c.MockFSM.Restore(in)
}

func (c *countFSM) RestoreCount() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.restores
}

func storeBounds(s LogStore) (uint64, uint64) {
	f, _ := s.FirstIndex()
	l, _ := s.LastIndex()
	return f, l
}

// TestAssurance_ReachabilityDivergentSuffix builds a legal multi-node history in
// which a follower ends up holding an earlier-term entry at a later leader's
// snapshot index, then observes whether the rejoin needs any snapshot at all.
func TestAssurance_ReachabilityDivergentSuffix(t *testing.T) {
	conf := inmemConfig(t)
	conf.TrailingLogs = 0
	conf.SnapshotThreshold = 1 << 20
	conf.SnapshotInterval = time.Hour
	conf.HeartbeatTimeout = 1 * time.Second
	conf.ElectionTimeout = 1 * time.Second
	conf.LeaderLeaseTimeout = 1 * time.Second
	conf.CommitTimeout = 10 * time.Millisecond

	var fsms []*countFSM
	c := MakeClusterCustom(t, &MakeClusterOpts{
		Peers: 5, Bootstrap: true, Conf: conf, LongstopTimeout: 5 * time.Second,
		MakeFSMFunc: func() FSM { f := &countFSM{MockFSM: &MockFSM{}}; fsms = append(fsms, f); return f },
	})
	defer c.Close()

	deadline := time.Now().Add(12 * time.Second)
	for time.Now().Before(deadline) && c.Leader() == nil {
		time.Sleep(10 * time.Millisecond)
	}
	leader := c.Leader()
	if leader == nil {
		t.Fatalf("no leader")
	}
	followers := c.Followers()
	if len(followers) < 4 {
		t.Fatalf("want 4 followers, got %d", len(followers))
	}
	partner := followers[0]
	var others []*Raft
	for _, r := range c.rafts {
		if r != leader && r != partner {
			others = append(others, r)
		}
	}
	if len(others) != 3 {
		t.Fatalf("want 3 others, got %d", len(others))
	}

	// Isolate the leader from the other three, keeping leader<->partner.
	lt := c.trans[c.IndexOf(leader)]
	for _, o := range others {
		lt.Disconnect(o.localAddr)
		c.trans[c.IndexOf(o)].Disconnect(leader.localAddr)
	}

	base := leader.LastIndex()
	for i := 0; i < 5; i++ {
		leader.Apply([]byte(fmt.Sprintf("uncommitted-%d", i)), 0)
	}
	replicated := false
	for d := time.Now().Add(4 * time.Second); time.Now().Before(d); {
		if partner.LastIndex() > base {
			replicated = true
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	pf, pl := storeBounds(c.stores[c.IndexOf(partner)])
	caEvent(map[string]interface{}{"event": "divergent_prefix", "base_index": base,
		"partitioned_leader_last_index": leader.LastIndex(), "partner_last_index": partner.LastIndex(),
		"partner_store_first": pf, "partner_store_last": pl,
		"partner_replicated_uncommitted": replicated, "divergence_index": base + 1})
	if !replicated {
		t.Skipf("precondition not reached: partner last index %d never exceeded base %d", partner.LastIndex(), base)
	}

	// The majority side elects a successor with a shorter log.
	var successor *Raft
	for d := time.Now().Add(12 * time.Second); time.Now().Before(d); {
		for _, o := range others {
			if o.State() == Leader {
				successor = o
			}
		}
		if successor != nil {
			break
		}
		time.Sleep(10 * time.Millisecond)
	}
	if successor == nil {
		t.Skipf("precondition not reached: no successor elected by the majority side")
	}
	// A real command gives the successor's FSM something to snapshot.
	if err := successor.Apply([]byte("post-election"), 5*time.Second).Error(); err != nil {
		t.Fatalf("post-election apply: %v", err)
	}
	for d := time.Now().Add(5 * time.Second); time.Now().Before(d); {
		if successor.AppliedIndex() >= base+1 {
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	sf := successor.Snapshot()
	if err := sf.Error(); err != nil {
		t.Fatalf("snapshot: %v", err)
	}
	meta, rc, err := sf.Open()
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	snapIdx := meta.Index
	rc.Close()
	snf, snl := storeBounds(c.stores[c.IndexOf(successor)])
	caEvent(map[string]interface{}{"event": "successor_snapshot", "snapshot_index": snapIdx,
		"snapshot_term": meta.Term, "divergence_index": base + 1,
		"successor_term": successor.CurrentTerm(), "old_leader_term": leader.CurrentTerm(),
		"successor_last_index": successor.LastIndex(), "successor_applied_index": successor.AppliedIndex(),
		"successor_store_first": snf, "successor_store_last": snl})

	pidx := c.IndexOf(partner)
	before := fsms[pidx].RestoreCount()
	c.FullyConnect()
	time.Sleep(300 * time.Millisecond)
	early := fsms[pidx].RestoreCount()
	time.Sleep(1200 * time.Millisecond)
	late := fsms[pidx].RestoreCount()
	pf2, pl2 := storeBounds(c.stores[pidx])
	sf2, sl2 := storeBounds(c.stores[c.IndexOf(successor)])
	caEvent(map[string]interface{}{"event": "rejoin_observe", "restores_before": before,
		"restores_early": early, "restores_late": late,
		"partner_applied_index": partner.AppliedIndex(), "partner_last_index": partner.LastIndex(),
		"partner_store_first": pf2, "partner_store_last": pl2,
		"successor_applied_index": successor.AppliedIndex(), "successor_commit_index": successor.CommitIndex(),
		"successor_store_first": sf2, "successor_store_last": sl2})
}

